window.NARRATION = [{"dur": 22.725, "cues": [{"t": 0.1, "e": 4.812, "text": "BOX AI Agentは、検索だけのAIではありません。"}, {"t": 4.763, "e": 22.025, "text": "Box上に保存されている物件資料や価格表、PJコード、サービス枠管理表、稟議関連資料などをもとに、必要な情報の確認や要約、抽出、複数資料の整理まで、チャット形式で行うことができます。"}]}, {"dur": 19.863, "cues": [{"t": 0.1, "e": 12.662, "text": "Box AIは、単体で回答する一般的なチャットAIとは違い、Box上のPDFやExcel、パワーポイントなど、あらゆる形式の資料を参照しながら処理します。"}, {"t": 12.613, "e": 19.163, "text": "画像を含む資料の読み込みにも対応しており、精度の高い結果が得られやすい仕組みです。"}]}, {"dur": 37.488, "cues": [{"t": 0.1, "e": 5.0, "text": "Box AI Agentは、いくつかの層が重なってできています。"}, {"t": 4.95, "e": 9.7, "text": "土台にあるのが、みなさんのコンテンツへの安全なアクセスです。"}, {"t": 9.7, "e": 20.225, "text": "その上に、裏側で組み合わされる複数のAIモデル、与えられた指示、達成したい目的、そして利用できる機能やツールが重なります。"}, {"t": 20.225, "e": 28.025, "text": "コンテンツへのアクセスはBoxの権限の範囲内で行われ、指示の書き方によって結果が大きく変わります。"}, {"t": 28.025, "e": 36.788, "text": "Box上に資料が整理されているほど、検索や要約、一覧化、下書き作成などに活用しやすくなります。"}]}, {"dur": 37.687, "cues": [{"t": 0.1, "e": 6.0, "text": "Box内に点在する複数の資料を、横断して参照することもできます。"}, {"t": 5.95, "e": 21.725, "text": "物件資料や価格表、PJコード一覧、サービス枠管理表に加えて、広告宣伝費、工程表、収支表、契約書など、フォルダをまたいで散らばっている資料をAIがまわりながら参照します。"}, {"t": 21.725, "e": 30.038, "text": "そのうえで、物件ごとの基本情報や価格、PJコード、確認事項をひとつにまとめて出力します。"}, {"t": 30.038, "e": 36.987, "text": "資料を一つずつ開いて確認する手間を減らし、情報整理の初動を早めることができます。"}]}, {"dur": 31.412, "cues": [{"t": 0.1, "e": 8.562, "text": "Box内の資料をAIで活用しやすくするためには、共通のキーとなる情報を意識して保存することが重要です。"}, {"t": 8.512, "e": 19.15, "text": "当社では物件ごとにPJコードが紐づいているため、資料名やフォルダ名、ファイル内の記載には、できるだけPJコードを含めるようにしてください。"}, {"t": 19.15, "e": 30.712, "text": "これにより、異なる資料をまたいだ参照や紐づけがしやすくなり、後から検索・抽出・集約する際にも、必要な情報を正確に引き出しやすくなります。"}]}, {"dur": 38.138, "cues": [{"t": 0.1, "e": 7.612, "text": "具体的な使い方としては、対象となるファイルやフォルダを選び、その内容について質問します。"}, {"t": 7.562, "e": 25.475, "text": "このフォルダ内の資料を要約してください、物件名とPJコードを一覧化してください、価格情報を整理してください、サービス枠管理表からこの物件の残額を確認してください、稟議・決裁資料の下書きを作成してください、といった形です。"}, {"t": 25.475, "e": 31.363, "text": "ただし、今できるのはここまでで、出力形式もまだ限定的です。"}, {"t": 31.363, "e": 37.438, "text": "実際のファイルを編集するなど、タスクそのものを完了させることはまだできません。"}]}, {"dur": 38.638, "cues": [{"t": 0.1, "e": 2.587, "text": "実際にやってみた例です。"}, {"t": 2.538, "e": 8.35, "text": "物件リストにPJコードと価格を付与し、顧客情報を紐づけてみました。"}, {"t": 8.35, "e": 16.312, "text": "物件概要が収納されているフォルダを指定して、中のファイルの概要を見やすくHTMLにまとめてみました。"}, {"t": 16.312, "e": 27.525, "text": "さらに、フォルダ内の事業収支や収支経緯表、サービス枠管理表を分析させて、決裁の定型文に合わせた文章と数字を出力してみました。"}, {"t": 27.525, "e": 32.175, "text": "このまま、ラクモのワークフローに貼る形に調整できます。"}, {"t": 32.175, "e": 37.938, "text": "点在する情報を、確認しやすい形に整理する用途で活用できます。"}]}, {"dur": 31.063, "cues": [{"t": 0.1, "e": 4.487, "text": "AIは、それぞれのBox権限の中で動きます。"}, {"t": 4.438, "e": 11.25, "text": "そのため、自分の権限が及ぶ範囲に情報を蓄積していくイメージで資料を集めてください。"}, {"t": 11.25, "e": 21.562, "text": "その際は、AIが突合させやすいように、PJコードなど一定のキーを中心に整理しながら格納すると、後から探しやすくなります。"}, {"t": 21.562, "e": 30.363, "text": "なお、GoogleワークスペースとBoxの連携は許可されているため、Gmailの本文をBoxに蓄積する機能もあります。"}]}, {"dur": 32.063, "cues": [{"t": 0.1, "e": 2.962, "text": "プロンプトの書き方も重要です。"}, {"t": 2.913, "e": 10.438, "text": "対象となる資料、確認したい項目、出力の形を、そのまま具体的に書いてください。"}, {"t": 10.438, "e": 23.15, "text": "例えば、このフォルダの内容を突合して、決裁資料用の売価、税額、サービス枠残額、粗利などの数字をまとめて表示してください、といった形です。"}, {"t": 23.15, "e": 31.363, "text": "見てほしい資料と、欲しい項目、出したい形を丁寧に書くほど、実務で使いやすい結果になります。"}]}, {"dur": 26.087, "cues": [{"t": 0.1, "e": 1.863, "text": "注意点です。"}, {"t": 1.812, "e": 6.588, "text": "このAIは、背景などのコンテキストをまだ蓄積できません。"}, {"t": 6.588, "e": 11.812, "text": "そのため、毎回のプロンプトでしっかり説明する必要があります。"}, {"t": 11.812, "e": 20.613, "text": "特に初回のプロンプトが重要になりますので、事前にチャットGPTなどを活用してプロンプトを作成してから使ってみてください。"}, {"t": 20.613, "e": 25.387, "text": "うまく出力できたプロンプトは、ぜひ共有していきましょう。"}]}, {"dur": 27.488, "cues": [{"t": 0.1, "e": 4.638, "text": "また、BOX AIには1日の利用制限があります。"}, {"t": 4.588, "e": 8.637, "text": "制限を超えると、動作するモデルが下がります。"}, {"t": 8.637, "e": 14.213, "text": "この赤い表示が出たら、Box Agent Liteで動作している状態です。"}, {"t": 14.213, "e": 22.337, "text": "モデルが下がった後は、横断整理や複雑な下書きなどの重い作業は避けて、作業は軽めにしておきましょう。"}, {"t": 22.337, "e": 26.788, "text": "今後、プロンプトを含めて改善されていくと思います。"}]}, {"dur": 17.175, "cues": [{"t": 0.1, "e": 5.65, "text": "まずは身近なフォルダや管理表から、無理のない範囲で試してみてください。"}, {"t": 5.6, "e": 11.662, "text": "Box上に資料を整理・蓄積していくことが、今後の活用につながります。"}, {"t": 11.662, "e": 16.475, "text": "活用事例やうまくいったプロンプトは、ぜひご共有ください。"}]}];
